/**
 * RequestPayload 请求/响应原始报文，按策略留存。
 */
export interface RequestPayload {
  id: number /* uint */;
  log_id: number /* uint */;
  request_body: string;
  response_body: string;
  request_headers: JSONMap;
  response_headers: JSONMap;
  created_at: string;
}
/**
 * Setting 键值型系统设置。
 */
export interface Setting {
  key: string;
  value: JSONMap;
  updated_at: string;
}

